import React from 'react';

interface Analytics {
  views: number;
  visitors: number;
  bounceRate: string;
}

interface Notification {
  id: number;
  message: string;
  type: 'info' | 'warning' | 'error';
}

interface Settings {
  theme: 'light' | 'dark';
  notificationsEnabled: boolean;
  language: string;
}

async function getDashboardData() {
  // Use absolute URL for server-side fetching
  // In a real app, this would come from an environment variable
  const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3000';

  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then(r => r.json()),
      fetch(`${baseUrl}/api/notifications`).then(r => r.json()),
      fetch(`${baseUrl}/api/settings`).then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    // Return mock data for build time as per existing pattern
    return {
      analytics: { 
        views: 1250, 
        visitors: 850,
        bounceRate: '45%' 
      },
      notifications: [
        { id: 1, message: 'System update available', type: 'info' },
        { id: 2, message: 'Server load high', type: 'warning' }
      ] as Notification[],
      settings: { 
        theme: 'light', 
        notificationsEnabled: true,
        language: 'en' 
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold">Dashboard Content</h2>

      <div className="grid gap-6 md:grid-cols-3">
        {/* Analytics Section */}
        <div className="p-4 border rounded shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Analytics</h3>
          <div className="space-y-1">
            <p>Views: <span className="font-medium">{analytics.views}</span></p>
            <p>Visitors: <span className="font-medium">{analytics.visitors}</span></p>
            <p>Bounce Rate: <span className="font-medium">{analytics.bounceRate}</span></p>
          </div>
        </div>

        {/* Notifications Section */}
        <div className="p-4 border rounded shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Notifications</h3>
          {notifications.length > 0 ? (
            <ul className="list-disc list-inside space-y-1">
              {notifications.map((note: Notification) => (
                <li key={note.id} className="text-sm">
                  {note.message}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-500">No new notifications</p>
          )}
        </div>

        {/* Settings Section */}
        <div className="p-4 border rounded shadow-sm">
          <h3 className="text-xl font-semibold mb-2">Settings</h3>
          <div className="space-y-1">
            <p>Theme: <span className="capitalize">{settings.theme}</span></p>
            <p>Notifications: <span>{settings.notificationsEnabled ? 'On' : 'Off'}</span></p>
            <p>Language: <span className="uppercase">{settings.language}</span></p>
          </div>
        </div>
      </div>
    </div>
  );
}

