import React from 'react';

interface Analytics {
  views: number;
  visitors: number;
  bounceRate: string;
}

interface Notification {
  id: number;
  message: string;
  type: 'info' | 'warning' | 'error';
}

interface Settings {
  theme: 'light' | 'dark';
  notificationsEnabled: boolean;
  language: string;
}

async function getDashboardData() {
  // Use absolute URL for server-side fetching
  // In a real app, this would come from an environment variable
  const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3000';

  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then(r => r.json()),
      fetch(`${baseUrl}/api/notifications`).then(r => r.json()),
      fetch(`${baseUrl}/api/settings`).then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    // Return mock data for build time as per existing pattern
    return {
      analytics: { 
        views: 1250, 
        visitors: 850,
        bounceRate: '45%' 
      },
      notifications: [
        { id: 1, message: 'System update available', type: 'info' },
        { id: 2, message: 'Server load high', type: 'warning' }
      ] as Notification[],
      settings: { 
        theme: 'light', 
        notificationsEnabled: true,
        language: 'en' 
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <div style={{ display: 'flex', gap: '20px' }}>
        {/* Analytics Section */}
        <div style={{ border: '1px solid #ccc', padding: '10px' }}>
          <h3>Analytics</h3>
          <div>
            <p>Views: {analytics.views}</p>
            <p>Visitors: {analytics.visitors}</p>
            <p>Bounce Rate: {analytics.bounceRate}</p>
          </div>
        </div>

        {/* Notifications Section */}
        <div style={{ border: '1px solid #ccc', padding: '10px' }}>
          <h3>Notifications</h3>
          {notifications.length > 0 ? (
            <ul>
              {notifications.map((note: Notification) => (
                <li key={note.id}>
                  {note.message}
                </li>
              ))}
            </ul>
          ) : (
            <p>No new notifications</p>
          )}
        </div>

        {/* Settings Section */}
        <div style={{ border: '1px solid #ccc', padding: '10px' }}>
          <h3>Settings</h3>
          <div>
            <p>Theme: {settings.theme}</p>
            <p>Notifications: {settings.notificationsEnabled ? 'On' : 'Off'}</p>
            <p>Language: {settings.language}</p>
          </div>
        </div>
      </div>
    </div>
  );
}
